import clsx from "clsx";
import type { ElementType } from "react";
import { getRuns, getText, type FormattedText } from "../../model/text";
import type { Endpoint } from "../../model/endpoints";
import { EndpointLink } from "./EndpointLink";
import styles from "./FormattedString.module.css";

export interface FormattedStringProps {
  text: FormattedText | null | undefined;
  as?: ElementType;
  className?: string;
  id?: string;
  title?: string;
  /** Renders run endpoints as plain text. */
  noLinks?: boolean;
}

/**
 * InnerTube formatted text. A single plain run renders as text; otherwise
 * each run is a span, a bold span or a link.
 */
export function FormattedString({ text, as: Tag = "span", className, id, title, noLinks }: FormattedStringProps) {
  const runs = getRuns(text);
  const label = text?.accessibility?.accessibilityData?.label;
  const plain = runs.length <= 1 && !runs[0]?.bold && !runs[0]?.italics && (noLinks || !runs[0]?.navigationEndpoint);
  return (
    <Tag className={clsx(styles.host, className)} id={id} title={title} aria-label={label || undefined}>
      {plain
        ? getText(text)
        : runs.map((run, i) => {
            const runClass = clsx(run.bold && styles.bold, run.italics && styles.italics);
            if (run.navigationEndpoint && !noLinks) {
              return (
                <EndpointLink key={i} endpoint={run.navigationEndpoint as Endpoint} className={clsx(styles.link, runClass)}>
                  {run.text}
                </EndpointLink>
              );
            }
            return (
              <span key={i} className={runClass || undefined}>
                {run.text}
              </span>
            );
          })}
    </Tag>
  );
}
