import { useDeferredValue, useEffect, useEffectEvent } from "react";

const PENDING = Symbol("pending");

/**
 * Calls `callback` after `value` has been committed, including what React
 * renders in the background for the same update: a deferred value updates
 * in the same background render as the other deferred values and initial
 * batches that the update caused, so its effect runs after all of them.
 * Undefined values are skipped.
 */
export function useOnSettled<T>(value: T | undefined, callback: (value: T) => void): void {
  const settled = useDeferredValue<T | undefined | typeof PENDING>(value, PENDING);
  const onSettled = useEffectEvent(callback);
  useEffect(() => {
    if (settled !== PENDING && settled !== undefined) onSettled(settled as T);
  }, [settled]);
}
