import { useDeferredValue, useRef, type ReactNode } from "react";
import type { ContinuationItemRenderer } from "../../model/innertube.gen";
import { useImpression } from "../../logging/impressions";
import { useOnVisible } from "../../hooks/useOnVisible";
import { Spinner } from "../spinner/Spinner";
import styles from "./ContinuationItem.module.css";

export interface ContinuationItemProps {
  data: ContinuationItemRenderer;
  onVisible: () => void;
  /** What shows while the next page loads; a spinner by default. */
  placeholder?: ReactNode;
  className?: string;
}

/** The end of a feed: a placeholder that loads the next page when it comes into view. */
export function ContinuationItem({ data, onVisible, placeholder, className }: ContinuationItemProps) {
  const ref = useRef<HTMLDivElement>(null);
  useImpression(ref, data);
  // The trigger arms in the background render that finishes the page, so a
  // page whose items are still rendering doesn't load the next one.
  const armed = useDeferredValue(true, false);
  useOnVisible(ref, onVisible, "0px", armed && data.trigger === "CONTINUATION_TRIGGER_ON_ITEM_SHOWN");
  return (
    <div ref={ref} className={className ?? styles.continuation} data-renderer="continuationItemRenderer">
      {placeholder ?? <Spinner />}
    </div>
  );
}
