import { useEffect, useEffectEvent, type RefObject } from "react";

// Shared IntersectionObservers, one per root margin.
const observers = new Map<string, IntersectionObserver>();
const callbacks = new WeakMap<Element, () => void>();

function observerFor(rootMargin: string): IntersectionObserver {
  let observer = observers.get(rootMargin);
  if (!observer) {
    observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) if (entry.isIntersecting) callbacks.get(entry.target)?.();
      },
      { rootMargin },
    );
    observers.set(rootMargin, observer);
  }
  return observer;
}

/** Calls `onVisible` each time the element comes within `rootMargin` of the viewport. */
export function useOnVisible(ref: RefObject<Element | null>, onVisible: () => void, rootMargin = "0px", enabled = true): void {
  const handleVisible = useEffectEvent(onVisible);
  useEffect(() => {
    const el = ref.current;
    if (!el || !enabled) return;
    const observer = observerFor(rootMargin);
    callbacks.set(el, () => handleVisible());
    observer.observe(el);
    return () => {
      observer.unobserve(el);
      callbacks.delete(el);
    };
  }, [ref, rootMargin, enabled]);
}
