import clsx from "clsx";
import styles from "./Spinner.module.css";

/** An indeterminate circular progress indicator. */
export function Spinner({ active = true, size = 32, className }: { active?: boolean; size?: number; className?: string }) {
  return (
    <div
      role="progressbar"
      aria-busy={active}
      className={clsx(styles.spinner, active && styles.active, className)}
      style={{ width: size, height: size }}
    >
      <div className={styles.layer}>
        <div className={clsx(styles.clipper, styles.left)}>
          <div className={styles.circle} />
        </div>
        <div className={clsx(styles.clipper, styles.right)}>
          <div className={styles.circle} />
        </div>
      </div>
    </div>
  );
}
