import { useEffect } from "react";
import { newScreen } from "../logging/screen";
import { navigationFinished, navigationStarted, startLatencyAction, type LatencyAction } from "../logging/telemetry";

/**
 * Starts the logging screen and latency action of a page navigation when
 * the page mounts. Call it before the page's queries, so that their
 * requests belong to the new screen. The page then calls
 * useNavigationFinished with whether its first content is there.
 */
export function useNavigationTelemetry(action: LatencyAction, page: string): void {
  useEffect(() => {
    newScreen();
    startLatencyAction(action);
    navigationStarted(page);
  }, [action, page]);
}

/** Finishes the navigation's latency action once the page has data. */
export function useNavigationFinished(hasData: boolean): void {
  useEffect(() => {
    if (hasData) navigationFinished();
  }, [hasData]);
}
