import clsx from "clsx";
import { useLayoutEffect, useRef, useState } from "react";
import type { MetadataBadgeRenderer } from "../../model/innertube.gen";
import { getText, type FormattedText } from "../../model/text";
import { FormattedString } from "../text/FormattedString";
import { Tooltip } from "../feedback/Tooltip";
import { BadgeList } from "../badge/MetadataBadge";
import styles from "./ChannelName.module.css";

export interface ChannelNameProps {
  name: FormattedText | null | undefined;
  badges?: Array<{ metadataBadgeRenderer?: MetadataBadgeRenderer }>;
  wrapText?: boolean;
  className?: string;
  id?: string;
}

/**
 * A channel name with its link, a tooltip with the full name, and badges.
 * Verified artists get a background pill sized to the text.
 */
export function ChannelName({ name, badges, wrapText, className, id }: ChannelNameProps) {
  const textRef = useRef<HTMLDivElement>(null);
  const artist = !!badges?.some((b) => b.metadataBadgeRenderer?.style === "BADGE_STYLE_TYPE_VERIFIED_ARTIST");
  const [pill, setPill] = useState<{ width: number; padding: number } | null>(null);
  const text = getText(name);
  useLayoutEffect(() => {
    const el = textRef.current;
    if (!artist || !el) return;
    const lineHeight = parseFloat(getComputedStyle(el).lineHeight) || 0;
    setPill({ width: el.scrollWidth, padding: Math.min(lineHeight, 20) / 2 });
  }, [artist, text]);
  return (
    <div className={clsx(styles.channelName, wrapText && styles.wrap, artist && styles.artist, className)} id={id}>
      <div className={styles.container}>
        <div
          ref={textRef}
          className={styles.textContainer}
          style={pill ? { width: pill.width, padding: `0 ${pill.padding}px` } : undefined}
        >
          <FormattedString text={name} className={styles.text} />
        </div>
        <Tooltip text={text} position="top" />
      </div>
      <BadgeList badges={badges} className={styles.badges} />
    </div>
  );
}
