import clsx from "clsx";
import { TouchFeedback } from "../feedback/TouchFeedback";
import styles from "./ChipShape.module.css";

export interface ChipShapeProps {
  text: string;
  selected: boolean;
  label?: string;
  onClick?: () => void;
}

/** A filter chip: a toggle button in a chip bar. */
export function ChipShape({ text, selected, label, onClick }: ChipShapeProps) {
  return (
    <div className={styles.host} role="presentation">
      <button type="button" className={styles.button} aria-pressed={selected} aria-label={label} data-chip="" onClick={onClick}>
        <div className={clsx(styles.chip, selected ? styles.active : styles.inactive)}>
          <div className={styles.text}>{text}</div>
          <TouchFeedback />
        </div>
      </button>
    </div>
  );
}
