import { applyEntityMutations, type EntityMutation } from "../state/entities";
import { adsOpportunityReceived } from "../logging/ads";
import { countResponse } from "../logging/telemetry";
import { flattenCommand, type Endpoint } from "./endpoints";

export interface ResponseBase {
  responseContext?: { serviceTrackingParams?: Array<{ service?: string; params?: Array<{ key?: string; value?: string }> }> };
  frameworkUpdates?: { entityBatchUpdate?: { mutations?: EntityMutation[] } };
  onResponseReceivedCommands?: Endpoint[];
  onResponseReceivedActions?: Endpoint[];
  onResponseReceivedEndpoints?: Endpoint[];
}

export interface Processed<T> {
  response: T;
  /** The commands the response asks the client to run, flattened. */
  commands: Endpoint[];
}

/**
 * Runs the client-side response processing: entity mutations go to the
 * entity store, ad opportunities to the ads logger, and the received
 * commands are collected for the caller.
 */
export function processResponse<T extends ResponseBase>(response: T): Processed<T> {
  countResponse(response.responseContext ? "ok" : "missing");
  const mutations = response.frameworkUpdates?.entityBatchUpdate?.mutations;
  if (mutations) applyEntityMutations(mutations);
  const commands: Endpoint[] = [];
  for (const list of [response.onResponseReceivedCommands, response.onResponseReceivedActions, response.onResponseReceivedEndpoints]) {
    for (const command of list ?? []) {
      for (const c of flattenCommand(command)) {
        if (c.adsControlFlowOpportunityReceivedCommand) adsOpportunityReceived(c.adsControlFlowOpportunityReceivedCommand);
        else commands.push(c);
      }
    }
  }
  return { response, commands };
}

export function parseResponse<T extends ResponseBase>(text: string): Processed<T> {
  return processResponse(JSON.parse(text) as T);
}
